	/*
     * @param	event CreateAllergyEvent
     */
    @EventHandler( payloadType=CreateAllergyEvent.class )
    public void handle( CreateAllergyEvent event) {
	    LOGGER.info("handling CreateAllergyEvent - " + event );
	    Allergy entity = new Allergy();
            entity.setAllergyId( event.getAllergyId() );
            entity.setSubstance( event.getSubstance() );
            entity.setReaction( event.getReaction() );
            entity.setSeverity( event.getSeverity() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAllergy( entity );
    }

    /*
     * @param	event UpdateAllergyEvent
     */
    @EventHandler( payloadType=UpdateAllergyEvent.class )
    public void handle( UpdateAllergyEvent event) {
    	LOGGER.info("handling UpdateAllergyEvent - " + event );
    	
	    Allergy entity = new Allergy();
            entity.setAllergyId( event.getAllergyId() );
            entity.setSubstance( event.getSubstance() );
            entity.setReaction( event.getReaction() );
            entity.setPatient( event.getPatient() );
            entity.setSeverity( event.getSeverity() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindAllergy( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAllergy( entity );        
    }
    
