/**
 * emit to subscription queries of type FindAllergy,
 * but only if the id matches
 *
 * @param		entity	Allergy
 */
	protected void emitFindAllergy( Allergy entity ) {
		LOGGER.info("handling emitFindAllergy" );
		
	    queryUpdateEmitter.emit(FindAllergyQuery.class,
	                            query -> query.getFilter().getAllergyId().equals(entity.getAllergyId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAllergy
	 * 
	 * @param		entity	Allergy
	 */
	protected void emitFindAllAllergy( Allergy entity ) {
		LOGGER.info("handling emitFindAllAllergy" );
		
	    queryUpdateEmitter.emit(FindAllAllergyQuery.class,
	                            query -> true,
	                            entity);
	}

